INSERT INTO scheduled_tasks (id, agent_id, name, description, schedule_type, cron_expression, action, action_params, status, last_run, next_run, run_count, fail_count, created_at, enabled) VALUES
('coo-morning-brief', 'coo-productivity', 'Morning Planning Brief', 'Prepare daily briefing before user wakes — focus tasks, anomalies, targets', 'cron', '45 6 * * *', 'custom_prompt', '{"prompt":"Execute Morning Planning Brief. Step 1: Call lifeos_context_card with agent=productivity for quick operational snapshot. Step 2: Call lifeos_daily_briefing with date=today for full daily picture. Step 3: Call lifeos_tasks with status=Focus to identify today''s priority tasks. Step 4: Call lifeos_weekday_patterns with include_today=true to compare today vs typical pattern. Step 5: Check lifeos_tasks with overdue_only=true for any overdue items. Produce: 1) Top 3 focus tasks for today, 2) Schedule anomalies detected, 3) Target vs actual comparison, 4) Suggested daily plan. If all clear: reply HEARTBEAT_OK. If signals detected: produce brief with actionable recommendations.","priority":"P2"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('coo-evening-review', 'coo-productivity', 'Daily Evening Review', 'Log day outcomes, compare vs targets, suggest tomorrow focus', 'cron', '30 21 * * *', 'custom_prompt', '{"prompt":"Execute Daily Evening Review. Step 1: Call lifeos_productivity_report with period=past_week to see weekly context. Step 2: Compare today''s actual activity vs targets from Activity Types. Step 3: Call lifeos_tasks to check completion status of today''s planned tasks. Step 4: Identify any tasks that slipped or were not completed. Produce: 1) Day summary — what was accomplished, 2) Target compliance — which categories met targets, which fell short, 3) Tomorrow''s suggested focus — top 3 tasks, 4) Flag any patterns of sustained underperformance (3+ days missing same target). If targets met: reply HEARTBEAT_OK. If significant gaps: produce brief with recommendations.","priority":"P2"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('coo-weekly-analysis', 'coo-productivity', 'Weekly Productivity Analysis', 'Deep weekly review with trajectory, temporal analysis, and cross-domain correlation', 'cron', '0 20 * * 0', 'custom_prompt', '{"prompt":"Execute Weekly Productivity Analysis. Step 1: Call lifeos_productivity_report with period=past_week for comprehensive weekly data. Step 2: Call lifeos_trajectory with period=past_week for target compliance and 30-day projections. Step 3: Call lifeos_temporal_analysis with period=past_week for time-based patterns. Step 4: Call lifeos_correlate with period=past_week for cross-domain correlations. Step 5: Call lifeos_weekday_patterns with period=past_month for weekday profile updates. Produce: 1) Weekly productivity report — time allocation, task completion, target gaps, 2) Trajectory assessment — improving, stable, or declining trends, 3) Habit compliance summary, 4) Cross-domain correlation insights. Save report to reports DB via lifeos_create_report. SYSTEMIC FLAG CHECK: If productivity declining 7+ consecutive days, task completion below 50% for the week, or activity patterns show burnout signals → send message.send to ceo-strategic with pattern flag. Do NOT write to systemic_journal.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('coo-monthly-synthesis', 'coo-productivity', 'Monthly Operational Synthesis', 'Monthly operational summary with month-over-month trends and resource allocation', 'cron', '0 18 L * *', 'custom_prompt', '{"prompt":"Execute Monthly Operational Synthesis. Step 1: Call lifeos_productivity_report with period=past_month for monthly overview. Step 2: Call lifeos_trajectory with period=past_month for monthly trend analysis and projections. Step 3: Call lifeos_temporal_analysis with period=past_month for temporal patterns. Step 4: Review habit compliance across all Activity Types targets. Step 5: Compare this month vs previous month trends. Produce: 1) Month-over-month trends for each activity category, 2) Habit compliance summary — which habits are consistent, which are slipping, 3) Resource allocation assessment — time budget vs actual allocation, 4) Operational health score — overall productivity trend direction, 5) Recommendations for next month — what to adjust, what to maintain. Save comprehensive monthly report to reports DB via lifeos_create_report. SYSTEMIC FLAG CHECK: If sustained underperformance across 2+ weeks for multiple categories → send message.send to ceo-strategic with systemic pattern flag.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1);
